const waterCirclesInnboElite: readonly Row[] = [
  ["innbo.objekter", "Forsikrede objekter – Elite-særgrenser", "Inntil 20 000 kr for penger og verdipapirer, 40 000 kr for hver av de angitte syklene, fritidsbåtene, tilhengerne og andre oppførte objekter etter vilkåret, samt samlet inntil 100 000 kr for yrkesløsøre og varer på forsikringsstedet.", "E.2", 13],
  ["tyveri.ute.grense", "Tyveri fra privat uteareal", "Inntil 50 000 kr ved tyveri fra privat boligs uteareal.", "E.2.11", 13],
  ["tyveri.bod.grense", "Tyveri fra bod i fellesareal", "Inntil 100 000 kr fra bod med adgang fra felles kjeller, loft, garasje eller annet fellesareal. Særlig tyveriutsatte ting og gjenstander over 50 000 kr skal ikke oppbevares der.", "E.2.14", 13],
  ["tyveri.utvidet", "Utvidet tyveridekning", "Elite utvider dekning for enkelte tyverier fra kjøretøy, båt og angitte bokser eller oppbevaringssteder i Norden. Risikogjenstander og sykkel følger særregler om oppbevaring, lås og sum.", "E.1.1–E.1.2", 12],
  ["sykkel.tyveri.laas", "Sykkel fra privat låst bolig eller garasje", "Ved tyveri fra låst bolig eller privat låst garasje er grensen 50 000 kr. Fellesgarasje omfattes ikke av denne særregelen. Sykkel kan få 10 % årlig aldersfradrag fra tre år, høyst 80 %.", "E.1.4", 12],
  ["uhell.grense", "Uhell og fall utenfor bolig", "Ved uhell utenfor bolig og skade ved at ting faller eller velter gjelder særgrense 100 000 kr per skadetilfelle etter reglene. Produksjonsfeil, slitasje og andre særskilte unntak må vurderes.", "E.1.3", 12],
  ["flytting.dekning", "Flytteskade ved egen transport", "Privat flytting med bil eller tilhenger, inkludert bæring mellom bolig og kjøretøy, omfattes inntil innbosummen, maksimalt 50 000 kr per enkeltgjenstand.", "E.1.3", 12],
  ["uhell.ombygging", "Tilpasning ved rullestolbehov", "Inntil 250 000 kr til ombygging i egen bolig etter angitt ulykke eller medfødt tilstand, ved minst 50 % varig medisinsk invaliditet. Utgiftene må påløpe innen fem år. Ved medfødt tilstand må invaliditetsgraden fastslås innen to år.", "E.1.5", 13],
  ["flytting.midlertidig_bosted", "Midlertidig bosted etter skade", "Merutgifter til opphold utenfor den faste boligen etter skade uten beløpsgrense i dette punktet. Forsikringsvilkårenes øvrige krav gjelder.", "E.2.9", 13],
  ["innbo.frysevarer", "Matvarer i fryser", "For dekket skade på matvarer i fryser har Elite ingen særskilt beløpsgrense i dette punktet.", "E.2.16", 13],
  ["vann.vaeske.grense", "Tap av gass og væske", "Inntil 20 000 kr for tap av gass, vann eller annen væske som omfattes.", "E.2.17", 13],
  ["innbo.aldersfradrag.elite", "Særregler for ny elektronikk", "I særordningen for nyere privat elektronikk og husholdningsapparater gjelder grense 20 000 kr for tyveri utenfor bolig og 100 000 kr for øvrige skader. Vilkåret har alderskrav, kjøpskvittering og objekt- og skadeunntak. Mobiltelefon og smartklokke har ett års grense for denne særberegningen.", "E.3, side 13–14", 14],
  ["idtyveri.dekning", "ID-tyveri", "Døgnåpen hjelp til å oppdage og begrense misbruk og juridisk bistand inntil 500 000 kr per ID-tyveri etter vilkåret. Forsikringsbeviset, bosted og familiekretser styrer hvem og hvor.", "E.4.1–E.4.4", 14],
  ["idtyveri.unntak", "ID-tyveri – sikkerhet og avgrensning", "Begivenheten må meldes og sikrede må samarbeide. Blant annet visse kort- og bankvilkårsbrudd, næringsrelaterte forhold og økonomisk tap som sådan begrenser dekningen.", "E.4.4–E.4.5", 15],
  ["nettmisbruk.dekning", "Hjelp med krenkende nettinnhold", "Bistand fra Mehrwerk til å fjerne krenkende innhold eller falske profiler. Avhenger av lovlighet, tilgang, språk og samarbeid; uten garanti for fjerning.", "E.4.6, side 15–16", 15],
  ["skadedyr.egenandel", "Skadedyrbekjempelse – egenandel", "2 000 kr per skade hvis ikke annen egenandel står i beviset.", "F.7", 16, undefined, "coverage"],
  ["skadedyr.unntak", "Skadedyr – unntak og skademelding", "Dekker bekjempelse, ikke skade på innbo, tidligere aktivitet, forebygging, indirekte tap eller ikke godkjente tiltak. Meld uten ugrunnet opphold og senest innen ett år etter kunnskap.", "F.5–F.6", 16],
  ["skadedyr.sikkerhet", "Sikkerhetskrav ved skadedyr", "Sikrede skal etterse og vedlikeholde, følge pålegg om utbedring og legge til rette for besiktigelse og bekjempelse. Manglende etterlevelse kan gi avkortning.", "F.9", 17],
];

const waterCirclesReiseCommon: readonly Row[] = [
  ["personer.omfang", "Hvem som er forsikret", "Personer i forsikringsbeviset må oppfylle reglene for folkeregistrering, bosted og norsk folketrygd. Ved familiedekning omfattes de angitte familiemedlemmene. Barn omfattes fram til fylte 21 år, med adressekrav i punkt 1.2.", "1.2", 3],
  ["omrade.utestengt", "Reiser og hendelser med særskilte unntak", "Streik, lockout og konkurs, tapt arbeidsfortjeneste, definerte ekspedisjoner og visse reiser ved krig, terror, politisk uro, katastrofe, epidemi eller reiseadvarsel er særskilt avgrenset. Evakueringspunktet har egne regler når en hendelse oppstår under reisen.", "1.4–1.9", 4],
  ["evakuering", "Evakuering og midlertidig opphold", "Ved angitte hendelser kan nødvendig evakuering dekkes etter råd eller godkjenning. Inntil 30 000 kr per person og 60 000 kr per familie til retur er mulig, maksimalt 30 dager etter hendelsen.", "1.3, side 3–4", 4],
  ["avbestilling.vilkar", "Avbestilling – hendelser og hvem som må rammes", "Dekker avbestilling på de angitte vilkårene ved blant annet uventet akutt sykdom, ulykke, dødsfall og navngitte hendelser på reisemålet. Avbestilling må skje før avreise og reglene for forholdet til den rammede, betaling og dokumentasjon gjelder.", "2.1–2.3, side 4–5", 4],
  ["avbestilling.unntak", "Avbestilling – unntak og andre refusjoner", "Blant annet visse forventede eller kjente forhold, avbrudd etter avreise og utgifter som kan refunderes fra andre er unntatt. Leverandør varsles og hendelse, betaling og økonomisk tap dokumenteres.", "2.5–2.6", 5],
  ["forsinkelse.vilkar", "Forsinkelse – dokumentasjon og unntak", "Forsinkelse og årsak dokumenteres skriftlig, med kvitteringer og planlagt reiserute. Bonuspoeng, utgift til mat og drikke og ansvar som ligger hos transportør eller arrangør omfattes ikke under disse punktene.", "3.1–3.4", 6],
  ["bagasje.forsinket_vilkar", "Forsinket bagasje – dokumentasjon", "PIR-rapport og originale kvitteringer kreves. Bare nødvendige kjøp mens bagasjen mangler dekkes, ikke kjøp på hjemreisen eller etter hjemkomst.", "3.5", 6],
  ["forsinkelse.tapte_utgifter", "Tapt hotellovernatting og arrangement", "Ved angitt årsak og minst åtte timers ankomstforsinkelse erstattes opptil 5 000 kr per person for én forhåndsbetalt overnatting og ett arrangement som ikke kunne brukes. Jobbreise og refunderbare utgifter er unntatt.", "3.7", 7],
  ["bagasje.dekning", "Reisegods", "Personlige ting, visse leide ting og innsjekket reisegods omfattes ved angitte hendelser som tyveri, ran, innbrudd, skadeverk, trafikkuhell, brann, vann- eller naturskade og bekreftet transportskade.", "4.1–4.4, side 7–8", 7],
  ["bagasje.unntak", "Reisegods – avgrensning av objekt og sted", "Blant annet kjøretøy, båter, flyttegods, yrkesgjenstander og enkelte samlinger er unntatt. Reisegods hjemme, på studiested i studietiden eller på fast arbeidssted i arbeidstiden er avgrenset av punkt 4.3.", "4.2–4.3", 7],
  ["bagasje.sikkerhet", "Sikkerhetsforskrifter for reisegods", "Hold tilsyn og lås oppbevaringssted forsvarlig. Penger, pass og billetter skal bæres eller låses inn. Verdisaker skal sikres, med egne krav for oppbevaring i kjøretøy og telt, transportemballasje og ting som ikke kan sendes i innsjekket bagasje.", "4.7", 8],
  ["bagasje.oppgjor", "Reisegods – oppgjør og unntak", "Gjenglemt eller bortkommet ting, kosmetisk skade, slitasje, ikke-fortollede ting og tap som andre skal dekke er blant avgrensningene. Selskapet kan velge reparasjon, tilsvarende ting eller penger med fradrag etter vilkåret.", "4.8–4.9, side 8–9", 9],
  ["bagasje.aldersfradrag", "Verdiforringelse på reisegods", "Årlig fradrag etter type, normalt 10 eller 20 %, maksimalt 80 %. For sykler angir tabellen tre år uten fradrag, og for blant annet mobiltelefon og sportsutstyr ett år.", "Verdiforringelsestabell, se 4.9", 19],
  ["medisinsk.unntak", "Reisesyke – hva som ikke omfattes", "Kjent og forventet behandlingsbehov, planlagt behandling, angitte private klinikker og steder eller aktiviteter som er unntatt, må vurderes etter vilkårene. Behandling etter retur hjem omfattes ikke av de ordinære reglene om reisesyke.", "5.3–5.4", 10],
  ["medisinsk.tann", "Tannbehandling på reise", "Tannbehandling etter ulykke inntil 5 000 kr, akutt tannsykdom inntil 1 000 kr etter vilkåret.", "5.5 b", 10],
  ["medisinsk.utgifter", "Nødvendige merutgifter ved sykdom", "Angitte utgifter til behandlingsreise, kost, overnatting og varsling kan dekkes. Med egen bil til lege eller behandling gjelder 2 kr per km. Dokumentasjon og forhåndsgodkjenning kreves som angitt.", "5.5", 10],
  ["sykeledsagelse.tilkalling", "Tilkalling og ledsagelse", "Rimelige, nødvendige reise- og oppholdsutgifter for inntil to personer i de tilfellene som beskrives. Vilkåret har særregler for endret reise når den eneste reiseledsager rammes.", "5.5", 11],
  ["hjemtransport.vilkar", "Forhåndsgodkjent hjemtransport", "Nødvendig syketransport må godkjennes på forhånd. Vilkåret dekker også angitt utsettelse eller endring av planlagt hjemreise, og har særregler om dødsfall og hjemkallelse.", "5.5 d–h", 10],
  ["medisinsk.dokumentasjon", "Melding og dokumentasjon", "Oppsøk lege snarest, følg behandlingsråd og ta vare på erklæring og originalkvitteringer. Forventes utgifter over 5 000 kr, gjelder krav om å varsle selskapets alarmsentral etter vilkåret.", "5.7", 11],
  ["medisinsk.aktiviteter", "Unntak for risikosport og behandling", "Blant annet angitte kampsporter, basehopping, banekjøring, kriminell handling og private klinikker i Norden er utelatt etter vilkårets regler.", "5.6", 11],
  ["ulykke.dekning", "Reiseulykke", "Forsikringen gjelder ved angitt ulykkesskade i avtaleperioden på reise. Varig medisinsk invaliditet, dødsfall og behandlingsutgifter følger forsikringsbeviset og vilkårets egne unntak og beregningsregler.", "6.1–6.2", 12],
  ["ulykke.alder", "Reiseulykke – aldersgrense og behandling", "Behandlingsutgifter erstattes normalt inntil 5 % av invaliditetssummen. Etter fylte 70 år er grensen for behandlingsutgifter 5 000 kr, og det utbetales ikke erstatning ved død eller invaliditet.", "6.2–6.3", 12],
  ["ulykke.unntak", "Ulykke – særskilte unntak", "Unntak for blant annet yrker og aktiviteter med høy risiko, sykdomsutløst hendelse, angitte medisinske tilstander, forgiftning, mindre arr, slagsmål og kriminalitet.", "6.4, side 12–13", 13],
  ["ulykke.invaliditet", "Oppgjør ved varig invaliditet", "Medisinsk invaliditetsgrad fastsettes etter tabell og den forsikrede summen. Forutgående funksjonstap, samvirkende årsaker og flere skader følger egne beregningsregler.", "6.5, side 13–14", 14],
  ["ulykke.dodsfall", "Oppgjør ved dødsfall", "Dødsfallet må skyldes ulykkesskaden og skje innen den angitte fristen. Eventuell tidligere invaliditetserstatning for samme ulykke og hvem som mottar oppgjøret følger punkt 6.5.", "6.5", 14],
  ["ansvar.dekning", "Privatansvar på reise", "Dekker rettslig erstatningsansvar i egenskap av privatperson ved person- eller tingskade etter vilkåret, på reiser utenfor Norden.", "7.1", 14],
  ["ansvar.unntak", "Reiseansvar – unntak og saksbehandling", "Blant annet erverv, fast eiendom, nærstående, lånte eller leide ting, motor, fartøy, gradvis forurensning og smitte er avgrenset. Krav meldes straks. Ansvar kan ikke erkjennes bindende uten selskapets samtykke.", "7.2–7.3, side 14–15", 15],
  ["rettshjelp.dekning", "Rettshjelp på reise", "Nødvendige advokatutgifter eller juridisk bistand i privat tvist utenfor Norden som krever bistand før reisen avsluttes, med nivåspesifikk forsikringssum. Idømte sakskostnader omfattes ikke.", "8.1", 15],
  ["rettshjelp.unntak", "Rettshjelp – avgrensninger", "Blant annet erverv, fast eiendom, familie- og arvesaker, visse kjøretøy-, straffe-, forvaltnings- og tvangssaker, salærtvister og utgifter før tvist er unntatt etter vilkåret.", "8.2, side 15–16", 16],
  ["rettshjelp.meldefrist", "Rettshjelp – frist og dokumentasjon", "Meld skriftlig så snart som mulig og senest ett år etter at advokat ble engasjert. Sikrede velger egnet advokat, begrenser utgiftene og må kunne dokumentere salær og medgått tid.", "8.3", 16],
  ["tjeneste.skadedyr", "Kakerlakker og veggedyr", "VIS bekjemper angitte skadedyr på forsikringsstedet eller i reisegods, inntil 50 000 kr per skade med maksimalt to bagasjeskader per år. Tidligere aktivitet, ikke godkjente tiltak og skade på selve tingene omfattes ikke.", "9.1–9.5", 16],
  ["tjeneste.skadedyr.egenandel", "Skadedyr – egenandel og sikkerhetsregler", "Egenandel 2 000 kr på forsikringsstedet om ikke annet står i beviset, og 500 kr for reisegods. Reisegods må pakkes og oppbevares slik at skadedyr ikke spres unødig.", "9.6–9.9", 17],
  ["tjeneste.kjaeledyr", "Veterinær ved akutt sykdom eller ulykke", "Inntil 1 000 kr per skade for nødvendig veterinærbehandling av medbrakt kjæledyr som omfattes, ved akutt sykdom eller ulykke på reise utenfor Norden innenfor EU/EØS. Dyr på vei til konkurranse har særskilt avgrensning.", "10.1–10.2, side 17–18", 18],
  ["oppgjor.melding", "Opplysningsplikt og aktsomhet", "Meld hendelsen snarest, gi riktige og fullstendige opplysninger og begrens tapet. Årsak og utgifter må sannsynliggjøres. Brudd på sikkerhetsforskrift eller grov uaktsomhet kan få følger etter reglene.", "11.1–11.2", 18],
  ["oppgjor.refusjon", "Dobbeltforsikring og regress", "Samlet erstatning kan ikke overstige tapet. Selskapet kan tre inn i kravet mot ansvarlig tredjepart. Feilaktig utbetalt erstatning kan kreves tilbake.", "11.4", 19],
  ["omrade.pandemi", "Pandemi – avvik fra de generelle vilkårene", "De uttrykkelige pandemiunntakene i de generelle vilkårene lempes for skader nevnt i reisepunktene 2 til 9, når forsikrede har fulgt UDs bestemmelser knyttet til utbruddet.", "12.1", 19],
];

